    assert(is_range(u) || is_vector(u) || is_finite(u), "\nInput u is invalid.")
    assert(is_range(v) || is_vector(v) || is_finite(v), "\nInput v is invalid.")
      !is_num(u) && !is_num(v) ?
          let(
