    id = info[1];
    tip = info[3];
    rounding = info[4];
    base = od - 2*tip;
    $fn = quantup(segs(od/2),12);
    attachable(anchor,spin,two_d=true,d=od){
        difference() {
            union() {
                circle(d=base);
                zrot_copies(n=2) {
                    hull() {
                        zrot_copies(n=3) {
                            translate([base/2,0,0]) {
                                circle(r=tip, $fn=$fn/2);
                            }
                        }
