       B = (r1-r2)/s,
       coefs = [B^2,
                2*A*B-2*r1+waist,
                A^2+(waist/2)^2 - r1^2],
       rts = waist<0 && approx(waist, 2*min(r1,r2))
                ? [-coefs[1]/2/coefs[0]]
                : quadratic_roots(coefs,real=true)
