bspp_dimensions = [
        [ 1/16,  [ 28, 0.3041 ]],
        [ 1/8,   [ 28, 0.3830 ]],
        [ 1/4,   [ 19, 0.5180 ]],
        [ 3/8,   [ 19, 0.6560 ]],
        [ 1/2,   [ 14, 0.8250 ]],
        [ 5/8,   [ 14, 0.9020 ]],
        [ 3/4,   [ 14, 1.0410 ]],
        [ 7/8,   [ 14, 1.1890 ]],
        [ 1,     [ 11, 1.3090 ]],
        [ 1+1/8, [ 11, 1.4920 ]],
        [ 1+1/4, [ 11, 1.6500 ]],
        [ 1+3/8, [ 11, 1.7450 ]],
        [ 1+1/2, [ 11, 1.8820 ]],
        [ 1+5/8, [ 11, 2.0820 ]],
        [ 1+3/4, [ 11, 2.1160 ]],
        [ 1+7/8, [ 11, 2.2440 ]],
        [ 2,     [ 11, 2.3470 ]],
