                || ( len(tree)==4 && is_num(tree[0]) && is_num(tree[1]) ) ),
            "\nThe tree is invalid.")
    len(tree)==1
    ?   assert( tree[0]==[] || is_vector(tree[0]), "\nThe tree is invalid." )
        [for(i=tree[0]) if(norm(points[i]-query)<=r) i ]
    :   norm(query-points[tree[0]]) > r+tree[1] ? [] :
        concat(
