    assert(in_list(style,["default","alt","quincunx", "convex","concave", "max_edge", "min_edge","min_area","flip1","flip2","quad"]))
    assert(is_matrix(points[0], n=3),"\nPoint array has the wrong shape or points are not 3d.")
